/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     int val;
 *     ListNode next;
 *     ListNode() {}
 *     ListNode(int val) { this.val = val; }
 *     ListNode(int val, ListNode next) { this.val = val; this.next = next; }
 * }
 */
class Solution {
    public ListNode deleteMiddle(ListNode head) {
        if (head.next == null) return null;
        if (head.next.next == null) {
            head.next=null;
            return head;
        }

        ListNode s=head;
        ListNode f=s;
        ListNode pre=s;


        while (f.next!=null && f.next.next!=null) {
            pre = s;
            s = s.next;
            f = f.next.next;
        }

        if (f.next == null){
            delete(pre, s);
            return head;
        }
        delete(pre.next, s.next);
        return head;
    }

    public void delete(ListNode previous, ListNode node) {
        node = node.next;
        previous.next = node;
    }
}

/**
 * Definition for singly-linked list.
 * public class ListNode {
 *     int val;
 *     ListNode next;
 *     ListNode() {}
 *     ListNode(int val) { this.val = val; }
 *     ListNode(int val, ListNode next) { this.val = val; this.next = next; }
 * }
 */
class Solution {
    public ListNode middleNode(ListNode head) {
        ListNode s;
        ListNode f;
        s = head; f = s;

        while (f.next!=null && f.next.next!=null) {
            s = s.next;
            f = f.next.next;
        }

        if (f.next == null){
            return s;
        }
        return s.next;
    }
}

class Solution { 
    public static int sum(int n) {
        int sum=0;
        while (n>0) {
            int d=n%10;
            n=n/10;
            sum += (d*d);
        }
        return sum;
    } 

    public boolean isHappy(int n) {
        int slow = n;
        int fast = n;

        while (fast!=1) {
            slow = sum(slow);
            fast = sum(fast);
            fast = sum(fast);
            if (slow==fast && slow!=1) {
                return false;
            }
        }
        return true;
    }
}

/**
 * Definition for singly-linked list.
 * class ListNode {
 *     int val;
 *     ListNode next;
 *     ListNode(int x) {
 *         val = x;
 *         next = null;
 *     }
 * }
 */
public class Solution {
    public boolean hasCycle(ListNode head) {
        ListNode s;
        ListNode f;

        if (head == null || head.next == null) return false; 

        s = head; f = s;

        while (f.next != null && f.next.next != null) {
            s = s.next; f = f.next.next;

            if (s == f) return true;
        }
        return false;
    }
}
